(() => {
  'use strict';
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const content=window.MISSION_CONTENT, translations=window.MISSION_TRANSLATIONS;
  const supported=window.MISSION_LANGUAGES;
  let lang='pl', filter='all', frequency='once', amount=50, method='bank', hearts=false;
  const storage={get:key=>{try{return localStorage.getItem(key)}catch{return null}},set:(key,value)=>{try{localStorage.setItem(key,value)}catch{}}};
  const params=new URLSearchParams(location.search);
  lang=supported.includes(params.get('lang'))?params.get('lang'):(supported.includes(storage.get('dp-language'))?storage.get('dp-language'):'pl');
  hearts=storage.get('dp-hearts')==='true';
  const t=key=>translations[lang][key]??translations.pl[key]??key;
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const multiline=value=>escape(value).replace(/\n/g,'<br>');
  function safeUrl(value,media=false){if(typeof value!=='string'||!value.trim()||(!media&&!/^https:\/\//i.test(value)))return '';try{const u=new URL(value,location.href);if(u.protocol==='https:'||(media&&['http:','file:'].includes(u.protocol)&&u.origin===location.origin))return u.href;}catch{}return '';}
  function field(item,name){return item.translations?.[lang]?.[name]||item.translations?.en?.[name]||item.translations?.pl?.[name]||(item[name+'Key']?t(item[name+'Key']):item[name]||'');}
  function openModal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
  function closeModal(){$('#modal-body').querySelectorAll('video').forEach(v=>v.pause());$('#modal').close();$('#modal-body').innerHTML='';}
  $('#modal-close').addEventListener('click',closeModal);
  $('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
  $('#modal').addEventListener('cancel',()=>{$('#modal-body').querySelectorAll('video').forEach(v=>v.pause());});
  let toastTimer;
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
  function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';$('#theme-toggle').setAttribute('aria-pressed',String(dark));$('#theme-toggle').setAttribute('aria-label',t(dark?'lightTheme':'darkTheme'));$('#theme-toggle').title=t(dark?'lightTheme':'darkTheme');$('#theme-toggle use').setAttribute('href','#'+(dark?'moon':'sun'));$('meta[name=theme-color]').content=dark?'#122123':'#f8f7f3';}
  $('#theme-toggle').addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';storage.set('dp-theme',document.documentElement.dataset.theme);syncTheme();});
  function renderGallery(){const items=content.gallery.filter(x=>filter==='all'||x.type===filter);$('#gallery-grid').classList.toggle('filtered',filter!=='all');$('#gallery-grid').innerHTML=items.map(item=>{const src=safeUrl(item.src,true);if(!src)return '';return `<button type="button" class="media-card" data-media="${escape(item.id)}" aria-label="${escape(field(item,'title'))}">${item.type==='video'?`<video src="${escape(src)}" muted playsinline preload="metadata" aria-hidden="true" tabindex="-1"></video><span class="play"><svg class="icon"><use href="#play"/></svg></span>`:`<img src="${escape(src)}" alt="${escape(field(item,'title'))}" loading="lazy">`}<span class="media-caption"><span><small>${escape(t(item.type==='video'?'videos':'photos'))}${item.demo?' / '+escape(t('sample')):''}</small><strong>${escape(field(item,'title'))}</strong></span><span class="arrow" aria-hidden="true">↗</span></span></button>`;}).join('');$$('[data-media]').forEach(button=>button.addEventListener('click',()=>showMedia(button.dataset.media)));}
  function showMedia(id){const item=content.gallery.find(x=>x.id===id);if(!item)return;const src=safeUrl(item.src,true);if(!src)return;const media=item.type==='video'?`<video class="modal-media" controls playsinline preload="metadata" src="${escape(src)}"><a href="${escape(src)}" download>${escape(t('videoFallback'))}</a></video>`:`<img class="modal-media" src="${escape(src)}" alt="${escape(field(item,'title'))}">`;openModal(`${media}<div class="modal-copy"><p class="eyebrow">${escape(t(item.type==='video'?'videos':'photos'))}</p><h2 id="modal-title">${escape(field(item,'title'))}</h2>${item.demo?`<p>${escape(t('mediaDemo'))}</p>`:''}<p>${escape(item.credit||'')}</p><div class="modal-actions">${content.gallery.length>1?'<button class="icon-button" id="media-prev" aria-label="←">←</button><button class="icon-button" id="media-next" aria-label="→">→</button>':''}</div></div>`);const index=content.gallery.indexOf(item);$('#media-prev')?.addEventListener('click',()=>showMedia(content.gallery[(index-1+content.gallery.length)%content.gallery.length].id));$('#media-next')?.addEventListener('click',()=>showMedia(content.gallery[(index+1)%content.gallery.length].id));}
  $('#gallery-filters').addEventListener('click',e=>{const button=e.target.closest('[data-filter]');if(!button)return;filter=button.dataset.filter;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderGallery();});
  function renderPosts(){const query=$('#blog-search').value.trim().toLocaleLowerCase(lang);const posts=content.posts.filter(p=>p.published!==false).filter(p=>[field(p,'title'),field(p,'excerpt'),p.categoryKey?t(p.categoryKey):p.category||''].join(' ').toLocaleLowerCase(lang).includes(query));$('#blog-grid').innerHTML=posts.map(p=>`<button class="post-card" data-post="${escape(p.id)}">${safeUrl(p.image,true)?`<div class="post-image"><img loading="lazy" src="${escape(safeUrl(p.image,true))}" alt="${escape(field(p,'title'))}"></div>`:''}<span class="post-meta">${escape(p.categoryKey?t(p.categoryKey):p.category||t('navBlog'))}${p.date?`<span>· ${escape(new Intl.DateTimeFormat(lang,{dateStyle:'medium'}).format(new Date(p.date+'T12:00:00')))}</span>`:''}${p.demo?`<span class="sample-badge">${escape(t('sample'))}</span>`:''}</span><h3>${escape(field(p,'title'))}</h3><p>${escape(field(p,'excerpt'))}</p><span class="text-link">${escape(t('read'))}<span aria-hidden="true">↗</span></span></button>`).join('')||`<p class="empty">${escape(t('noPosts'))}</p>`;$$('[data-post]').forEach(b=>b.addEventListener('click',()=>showPost(b.dataset.post)));}
  function showPost(id){const p=content.posts.find(p=>p.id===id&&p.published!==false);if(!p)return;const image=safeUrl(p.image,true);openModal(`${image?`<img class="modal-media" style="max-height:310px;object-fit:cover" src="${escape(image)}" alt="">`:''}<article class="modal-copy"><p class="eyebrow">${escape(p.categoryKey?t(p.categoryKey):p.category||t('navBlog'))}${p.demo?' / '+escape(t('sample')):''}</p><h2 id="modal-title">${escape(field(p,'title'))}</h2><p><strong>${escape(field(p,'excerpt'))}</strong></p><p>${escape(field(p,'body'))}</p>${p.demo?`<p class="small-note">${escape(t('blogNote'))}</p>`:''}<a class="text-link" href="#contact" id="post-contact">${escape(t('join'))} ↗</a></article>`);$('#post-contact').addEventListener('click',closeModal);}
  $('#blog-search').addEventListener('input',renderPosts);
  const paymentMethods=[['bank',()=>t('bank'),'bankDesc'],['blik',()=> 'BLIK','blikDesc'],['paypal',()=> 'PayPal','onlineDesc'],['przelewy24',()=> 'Przelewy24','onlineDesc'],['payu',()=> 'PayU','onlineDesc'],['revolut',()=> 'Revolut','onlineDesc'],['zrzutka',()=> 'Zrzutka','onlineDesc'],['patronite',()=> 'Patronite','onlineDesc']];
  function renderPayments(){const currency=$('#currency').value;$('#amount-currency').textContent=currency;const fmt=new Intl.NumberFormat(lang,{maximumFractionDigits:2});$('#donate-label').textContent=`${t('support')} · ${fmt.format(Number(amount)||0)} ${currency}`;$('#payment-methods').innerHTML=paymentMethods.map(([id,label])=>`<label class="payment-option" data-method="${id}"><input type="radio" name="method" value="${id}" ${id===method?'checked':''}><strong>${escape(label())}</strong></label>`).join('');const selected=paymentMethods.find(x=>x[0]===method);$('#payment-description').textContent=t(method==='bank'?'bankDesc':frequency==='monthly'?'recurringDesc':selected[2]);const configured=method==='bank'?Boolean(content.payments.bank?.recipient&&content.payments.bank?.iban):Boolean(paymentUrl());$('#payment-status').textContent=configured?'':t('paymentSetup');$('#payment-methods').querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{method=input.value;renderPayments();}));}
  function paymentUrl(){return safeUrl(content.payments[method]?.[frequency==='monthly'?'monthlyUrl':'oneTimeUrl']);}
  $$('.donation-frequency button').forEach(button=>button.addEventListener('click',()=>{frequency=button.dataset.frequency;$$('.donation-frequency button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderPayments();}));
  $$('[data-amount]').forEach(button=>button.addEventListener('click',()=>{amount=Number(button.dataset.amount);$('#custom-amount').value='';$$('[data-amount]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderPayments();}));
  $('#custom-amount').addEventListener('input',()=>{amount=$('#custom-amount').value;$$('[data-amount]').forEach(b=>b.setAttribute('aria-pressed','false'));renderPayments();});$('#currency').addEventListener('change',renderPayments);
  $('#donation-form').addEventListener('submit',e=>{e.preventDefault();if(!Number.isFinite(Number(amount))||Number(amount)<1||Number(amount)>1000000){toast(t('invalidAmount'));$('#custom-amount').focus();return;}const bank=content.payments.bank;const url=paymentUrl();const configured=method==='bank'?Boolean(bank?.recipient&&bank?.iban):Boolean(url);const summary=`${paymentMethods.find(x=>x[0]===method)[1]()} · ${new Intl.NumberFormat(lang,{maximumFractionDigits:2}).format(Number(amount))} ${$('#currency').value} · ${t(frequency==='monthly'?'monthly':'once')}`;
    if(!configured){openModal(`<div class="modal-copy"><p class="eyebrow">${escape(summary)}</p><h2 id="modal-title">${escape(t('unconfigured'))}</h2><p>${escape(t('setupBody'))}</p><div class="modal-actions"><a class="button" href="${escape(safeUrl(content.social.facebook))}" target="_blank" rel="noopener noreferrer">Facebook ↗</a><a class="button" href="${escape(safeUrl(content.social.instagram))}" target="_blank" rel="noopener noreferrer">Instagram ↗</a></div></div>`);return;}
    if(method==='bank'){const rows=[bank.recipient,bank.iban,bank.bic,bank.title].filter(Boolean);openModal(`<div class="modal-copy"><p class="eyebrow">${escape(summary)}</p><h2 id="modal-title">${escape(t('bank'))}</h2><p>${escape(t('bankDesc'))}</p><div class="bank-data">${rows.map(value=>`<span>${escape(value)}</span>`).join('')}</div><button class="button" id="copy-bank">${escape(t('copy'))}</button></div>`);$('#copy-bank').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(rows.join('\n'));toast(t('copied'));}catch{toast(t('copyFailed'));}});}
    else{openModal(`<div class="modal-copy"><p class="eyebrow">${escape(summary)}</p><h2 id="modal-title">${escape(paymentMethods.find(x=>x[0]===method)[1]())}</h2><p>${escape(t('onlineDesc'))}</p>${frequency==='monthly'?`<p>${escape(t('recurringDesc'))}</p>`:''}<a class="button" href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(paymentMethods.find(x=>x[0]===method)[1]())} ↗</a></div>`);}
  });
  function applyLanguage(next,updateUrl=true){lang=next;document.documentElement.lang=lang;document.title='Dobry Początek — '+t('navMission')+' / Good Start';$$('[data-t]').forEach(el=>{el.textContent=t(el.dataset.t);el.style.whiteSpace='pre-line';});$$('[data-placeholder]').forEach(el=>el.placeholder=t(el.dataset.placeholder));$$('[data-alt]').forEach(el=>el.alt=t(el.dataset.alt));$('#current-lang').textContent=lang.toUpperCase();$$('[data-lang]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.lang===lang)));$('#currency').setAttribute('aria-label',t('currency'));$('#gallery-filters').setAttribute('aria-label',t('navGallery'));$('#navigation').setAttribute('aria-label',t('navMission'));$('#modal-close').setAttribute('aria-label',t('close'));$('.back-top').setAttribute('aria-label',t('backTop'));$('#blog-search').setAttribute('aria-label',t('search'));storage.set('dp-language',lang);syncTheme();syncHearts();renderGallery();renderPosts();renderPayments();if(updateUrl){const url=new URL(location.href);url.searchParams.set('lang',lang);try{history.replaceState(null,'',url);}catch{}} }
  $$('[data-lang]').forEach(button=>button.addEventListener('click',()=>{if($('#modal').open)closeModal();applyLanguage(button.dataset.lang);$('#languages').open=false;}));
  document.addEventListener('click',e=>{if(!e.target.closest('#languages'))$('#languages').open=false;});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#languages').open=false;$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
  $('#menu-toggle').addEventListener('click',()=>{$('#navigation').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String($('#navigation').classList.contains('open')));});$$('#navigation a').forEach(a=>a.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}));
  $('#privacy-button').addEventListener('click',()=>openModal(`<div class="modal-copy"><h2 id="modal-title">${escape(t('privacy'))}</h2><p>${escape(t('privacyBody'))}</p></div>`));
  $('#credits-button').addEventListener('click',()=>openModal(`<div class="modal-copy"><h2 id="modal-title">${escape(t('credits'))}</h2><p>${escape(t('mediaDemo'))}</p><p><a href="https://unsplash.com/photos/a-group-of-people-putting-their-hands-together-h43DFZjMcDw" target="_blank" rel="noopener noreferrer">Creatopy / Unsplash</a><br><a href="https://unsplash.com/photos/an-open-bible-on-a-table-in-the-sunlight-SZaxKdLwz6o" target="_blank" rel="noopener noreferrer">Shane Hoving / Unsplash</a><br><a href="https://unsplash.com/photos/an-open-book-sitting-on-top-of-a-wooden-table-9tm5xu8kJdU" target="_blank" rel="noopener noreferrer">Jessica Mangano / Unsplash</a><br><a href="https://github.com/mdn/interactive-examples/tree/main/live-examples/media/cc0-videos" target="_blank" rel="noopener noreferrer">MDN / CC0 — flower.mp4</a></p><p>Inter / SIL Open Font License<br>Noto Sans Georgian & Armenian / SIL Open Font License</p></div>`));
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  function syncHearts(){$('#heart-toggle').setAttribute('aria-pressed',String(hearts));$('#heart-toggle').setAttribute('aria-label',t(hearts?'heartsOff':'heartsOn'));$('#heart-toggle').title=t(hearts?'heartsOff':'heartsOn');if(!hearts||reduced.matches)$('#heart-layer').replaceChildren();}
  function heart(x,y,burst=false){if(!hearts||reduced.matches||document.hidden||$('#heart-layer').childElementCount>38)return;const count=burst?7:1;for(let i=0;i<count;i++){const el=document.createElement('span');el.className='heart-particle';el.textContent='♡';el.style.cssText=`--x:${x-7}px;--y:${y-9}px;--dx:${(Math.random()-.5)*(burst?130:30)}px;--dy:${40+Math.random()*70}px;--rot:${(Math.random()-.5)*65}deg;font-size:${12+Math.random()*13}px`;$('#heart-layer').append(el);el.addEventListener('animationend',()=>el.remove(),{once:true});}}
  $('#heart-toggle').addEventListener('click',e=>{hearts=!hearts;storage.set('dp-hearts',String(hearts));syncHearts();const r=e.currentTarget.getBoundingClientRect();heart(r.x+r.width/2,r.y+r.height/2,true);});
  let last=0;document.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const now=performance.now();if(now-last<85)return;last=now;heart(e.clientX,e.clientY);},{passive:true});document.addEventListener('pointerdown',e=>heart(e.clientX,e.clientY,true),{passive:true});reduced.addEventListener('change',syncHearts);document.addEventListener('visibilitychange',()=>{if(document.hidden)$('#heart-layer').replaceChildren();});
  $('#year').textContent=new Date().getFullYear();
  $('.contact-links a:first-child').href=safeUrl(content.social.facebook);$('.contact-links a:last-child').href=safeUrl(content.social.instagram);$('.social-instagram').href=safeUrl(content.social.instagram);
  applyLanguage(lang,false);
})();
